(function() {
  if (window._cvDlDesignPatched) return;
  window._cvDlDesignPatched = true;

  function escHtml(s) {
    return String(s || '').replace(/[&<>"']/g, function(c) {
      return { '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c];
    });
  }

  function formatColoredMeta(label) {
    var raw = String(label || 'HD Download').trim();
    if (raw.indexOf('|') !== -1) {
      var parts = raw.split('|').map(function(p) { return p.trim(); }).filter(Boolean);
      return parts.map(function(p, idx) {
        var cls = idx === 0 ? 'cv-dl-part-1' : (idx === 1 ? 'cv-dl-part-2' : 'cv-dl-part-3');
        return '<span class="' + cls + '">' + escHtml(p) + '</span>';
      }).join('<span class="cv-dl-sep">|</span>');
    }
    var safe = escHtml(raw);
    safe = safe.replace(/\b(4K|2K|2160p|1440p|1080p|720p|480p|360p|SD|FHD|UHD|HD|WEB-DL|BluRay|HDRip|HEVC)\b/gi, '<span class="cv-dl-part-1">$1</span>');
    safe = safe.replace(/\b(\d+(?:\.\d+)?\s*(?:GB|MB))\b/gi, '<span class="cv-dl-part-3">$1</span>');
    return '<span class="cv-dl-part-2">' + safe + '</span>';
  }

  var dlIconSvg = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none"><path d="M12 3v12m0 0l-4.5-4.5M12 15l4.5-4.5M4 19h16" stroke="#ffffff" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';

  window.createQualityBtnElement = function(label, rawLink) {
    var finalLink = String(rawLink || '').trim();
    if (!/^https?:\/\//i.test(finalLink)) finalLink = 'https://' + finalLink;

    var card = document.createElement('div');
    card.className = 'cv-dl-card';
    card.innerHTML =
      '<div class="cv-dl-meta">' + formatColoredMeta(label) + '</div>' +
      '<button type="button" class="cv-dl-now-btn">' +
        dlIconSvg + '<span>DOWNLOAD NOW</span>' + dlIconSvg +
      '</button>';

    card.querySelector('.cv-dl-now-btn').onclick = function() {
      if (typeof tg !== 'undefined' && tg && tg.HapticFeedback) {
        tg.HapticFeedback.notificationOccurred('success');
      }
      if (typeof currentMovie !== 'undefined' && currentMovie && typeof trackMovieDownload === 'function') {
        trackMovieDownload(currentMovie.title);
      }
      if (typeof openSafeUrl === 'function') openSafeUrl(finalLink);
      else window.open(finalLink, '_blank');
    };

    return card;
  };

  var origRenderDl = window.renderDownloadButtons;
  if (typeof origRenderDl === 'function') {
    window.renderDownloadButtons = function() {
      origRenderDl();
      var container = document.getElementById('qualityContainer');
      if (container && !container.querySelector('.cv-dl-heading')) {
        var head = document.createElement('div');
        head.className = 'cv-dl-heading';
        head.innerHTML = '<span class="cv-dl-heading-bracket">[</span><span class="cv-dl-heading-text">⬇ Download Links ⬇</span><span class="cv-dl-heading-bracket">]</span>';
        container.insertBefore(head, container.firstChild);
      }
    };
  }
})();

