(function() {
  if (window._cvDiscoverySharePatched) return;
  window._cvDiscoverySharePatched = true;

  var serialCache = [];
  var similarCache = [];

  function escHtml(s) {
    return String(s || '').replace(/[&<>"']/g, function(c) {
      return { '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c];
    });
  }

  function extractSerialNum(title) {
    var t = String(title || '');
    var m = t.match(/\b(?:part|chapter|vol|volume|season|s|ep|episode)\s*0*(\d+)\b/i);
    if (m) return parseInt(m[1], 10);
    var rom = t.match(/\b(i|ii|iii|iv|v|vi|vii|viii|ix|x)\b(?:\s*\(\d{4}\))?$/i);
    if (rom) {
      var map = { i:1, ii:2, iii:3, iv:4, v:5, vi:6, vii:7, viii:8, ix:9, x:10 };
      return map[rom[1].toLowerCase()] || 0;
    }
    var noYear = t.replace(/\(\s*\d{4}\s*\)|\[\s*\d{4}\s*\]/g, '').trim();
    var endNum = noYear.match(/\s+(\d{1,2})$/);
    if (endNum) return parseInt(endNum[1], 10);
    return 1;
  }

  function getLooseBaseKey(title) {
    var base = (typeof extractBaseFranchiseTitle === 'function')
      ? extractBaseFranchiseTitle(title)
      : String(title || '');
    return base.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
  }

  function ensureExtraContainers() {
    var detail = document.getElementById('cineDetailView');
    if (!detail) return;

    if (!document.getElementById('cvSimilarSection')) {
      var sim = document.createElement('div');
      sim.id = 'cvSimilarSection';
      sim.className = 'cv-extra-section';
      sim.style.display = 'none';
      sim.innerHTML =
        '<div class="cv-extra-title">✨ আপনার জন্য আরও মুভি (Similar Titles)</div>' +
        '<div class="horizontal-scroll-row" id="cvSimilarRow"></div>';
      detail.appendChild(sim);
    }

    if (!document.getElementById('cvShareSection')) {
      var sh = document.createElement('div');
      sh.id = 'cvShareSection';
      sh.className = 'cv-extra-section';
      sh.innerHTML =
        '<div class="cv-extra-title" style="color:#facc15;">📤 বন্ধুদের মাঝে শেয়ার করুন</div>' +
        '<div class="cv-share-grid">' +
          '<button type="button" class="cv-share-btn cv-sh-fb" onclick="cvShareTo(\'fb\')"><span>📘</span><span>Facebook</span></button>' +
          '<button type="button" class="cv-share-btn cv-sh-wa" onclick="cvShareTo(\'wa\')"><span>💬</span><span>WhatsApp</span></button>' +
          '<button type="button" class="cv-share-btn cv-sh-tg" onclick="cvShareTo(\'tg\')"><span>✈️</span><span>Telegram</span></button>' +
          '<button type="button" class="cv-share-btn cv-sh-ms" onclick="cvShareTo(\'ms\')"><span>⚡</span><span>Messenger</span></button>' +
          '<button type="button" class="cv-share-btn cv-sh-tt" onclick="cvShareTo(\'tt\')"><span>🎵</span><span>TikTok</span></button>' +
          '<button type="button" class="cv-share-btn cv-sh-tw" onclick="cvShareTo(\'tw\')"><span>𝕏</span><span>X / Twitter</span></button>' +
          '<button type="button" class="cv-share-btn cv-sh-cp" onclick="cvShareTo(\'more\')"><span>🔗</span><span>Copy/More</span></button>' +
        '</div>';
      detail.appendChild(sh);
    }

    if (!document.getElementById('cvBottomHomeWrap')) {
      var hm = document.createElement('div');
      hm.id = 'cvBottomHomeWrap';
      hm.className = 'cv-bottom-home-wrap';
      hm.innerHTML = '<button type="button" class="cv-bottom-home-btn" onclick="closeCineDetail(); goHome();">🏠 হোম পেজে ফিরুন (Home)</button>';
      detail.appendChild(hm);
    }
  }

  window.cvOpenSerialCard = function(idx) {
    if (serialCache[idx]) openCineDetailWithObj(serialCache[idx]);
  };
  window.cvOpenSimilarCard = function(idx) {
    if (similarCache[idx]) openCineDetailWithObj(similarCache[idx]);
  };

  window.cvShareTo = function(platform) {
    if (!currentMovie) return;
    var url = window.location.origin + window.location.pathname + '?id=' + currentMovie.id;
    var text = '🎬 "' + currentMovie.title + '" HD মুভি দেখুন ও ডাউনলোড করুন CineVibeBD-তে!';

    if (platform === 'fb') {
      openSafeUrl('https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(url));
      return;
    }
    if (platform === 'wa') {
      openSafeUrl('https://api.whatsapp.com/send?text=' + encodeURIComponent(text + '\n' + url));
      return;
    }
    if (platform === 'tg') {
      openSafeUrl('https://t.me/share/url?url=' + encodeURIComponent(url) + '&text=' + encodeURIComponent(text));
      return;
    }
    if (platform === 'tw') {
      openSafeUrl('https://twitter.com/intent/tweet?text=' + encodeURIComponent(text) + '&url=' + encodeURIComponent(url));
      return;
    }

    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text + '\n' + url).catch(function(){});
    }

    if (navigator.share) {
      navigator.share({ title: currentMovie.title, text: text, url: url }).catch(function(){});
      return;
    }

    if (platform === 'ms') {
      openSafeUrl('fb-messenger://share/?link=' + encodeURIComponent(url));
      return;
    }
    if (platform === 'tt') {
      alert('✅ মুভির নাম ও লিংক কপি হয়েছে!\n\nএখন TikTok খুলে ভিডিও বা মেসেজে পেস্ট করে শেয়ার করুন:\n' + url);
      openSafeUrl('https://www.tiktok.com/');
      return;
    }
    alert('✅ লিংক কপি হয়েছে! যেকোনো অ্যাপে পেস্ট করে শেয়ার করুন:\n\n' + url);
  };

  function buildCardHtml(m, idx, fnName, badgeOverride) {
    var badge = badgeOverride || (m.isFromSheet ? (m.badge || 'HD') : 'SIMILAR');
    var badgeCls = m.isFromSheet ? '' : ' tmdb-part-badge';
    var r = String(m.rating || '7.5').replace(/[⭐★]/g, '').trim();
    return '<div class="movie-card" onclick="' + fnName + '(' + idx + ')">' +
      '<div class="movie-poster-wrap">' +
        '<div class="card-rating-badge"><span>★</span> ' + escHtml(r) + '</div>' +
        '<span class="quality-badge' + badgeCls + '">' + escHtml(badge) + '</span>' +
        '<img src="' + escHtml(m.image || '') + '" alt="' + escHtml(m.title) + '" loading="lazy" onerror="handleImageError(this)">' +
      '</div>' +
      '<div class="movie-info">' +
        '<div class="movie-title">' + escHtml(m.title) + '</div>' +
        '<div class="movie-submeta">' + escHtml(m.year || '2026') + ' · ' + (m.isFromSheet ? 'সাইটে আছে' : 'Similar') + '</div>' +
      '</div>' +
    '</div>';
  }

  async function loadSerialAndSimilar(movie) {
    ensureExtraContainers();
    var openedId = movie.id;

    // ১. একই মুভির সিরিয়াল পার্টস
    var relSec = document.getElementById('relatedPartsSection');
    var relRow = document.getElementById('relatedPartsRow');
    var relTitle = relSec ? relSec.querySelector('.related-parts-title') : null;
    if (relSec && relRow) {
      relSec.style.display = 'none';
      relRow.innerHTML = '';
      if (relTitle) relTitle.innerHTML = '🎞️ একই মুভির সব পার্ট / সিরিয়াল (Serial Order)';
    }

    var partsMap = new Map();
    function addPart(p) {
      if (!p || !p.title) return;
      var k = p.isFromSheet ? ('s_' + p.id) : (p.tmdbId ? 't_' + p.tmdbId : 'n_' + getLooseBaseKey(p.title) + '_' + extractSerialNum(p.title));
      if (!partsMap.has(k)) partsMap.set(k, p);
    }

    var baseKey = getLooseBaseKey(movie.title);
    if (baseKey.length >= 3 && Array.isArray(allMovies)) {
      allMovies.forEach(function(m) {
        if (getLooseBaseKey(m.title) === baseKey) addPart(m);
      });
    }

    var tmdbId = movie.tmdbId;
    var ep = (movie.mediaType || (movie.isSeries ? 'tv' : 'movie')) === 'tv' ? 'tv' : 'movie';
    if (!tmdbId && typeof TMDB_API_KEY !== 'undefined') {
      try {
        var cleaned = cleanTitleForSearch(movie.title) || movie.title;
        var sr = await resJsonSafe(await fetch('https://api.themoviedb.org/3/search/multi?api_key=' + TMDB_API_KEY + '&query=' + encodeURIComponent(cleaned)));
        var hit = (sr && sr.results || []).find(function(r) { return r.media_type === 'movie' || r.media_type === 'tv'; });
        if (hit) { tmdbId = hit.id; ep = hit.media_type; }
      } catch (e) {}
    }

    if (tmdbId && ep === 'movie') {
      try {
        var mData = await resJsonSafe(await fetch('https://api.themoviedb.org/3/movie/' + tmdbId + '?api_key=' + TMDB_API_KEY));
        if (mData && mData.belongs_to_collection && mData.belongs_to_collection.id) {
          var colData = await resJsonSafe(await fetch('https://api.themoviedb.org/3/collection/' + mData.belongs_to_collection.id + '?api_key=' + TMDB_API_KEY));
          (colData && colData.parts || []).forEach(function(p) {
            if (p.poster_path) {
              var localHit = findSheetMatchForPart(p.id, p.title);
              addPart(localHit || buildExternalMovieObj(Object.assign({}, p, { media_type: 'movie' }), ''));
            }
          });
        }
      } catch (e) {}
    }

    addPart(movie);
    var sortedParts = Array.from(partsMap.values()).sort(function(a, b) {
      var na = extractSerialNum(a.title);
      var nb = extractSerialNum(b.title);
      if (na !== nb) return na - nb;
      var ya = parseInt(a.year || '9999', 10);
      var yb = parseInt(b.year || '9999', 10);
      if (ya !== yb) return ya - yb;
      return String(a.title).localeCompare(String(b.title));
    });

    if (!currentMovie || currentMovie.id !== openedId) return;
    serialCache = sortedParts;
    if (sortedParts.length >= 2 && relSec && relRow) {
      relRow.innerHTML = sortedParts.map(function(p, idx) {
        var isCur = (p.id === movie.id && p.isFromSheet === movie.isFromSheet);
        var bTxt = isCur ? 'NOW #' + (idx + 1) : '#' + (idx + 1) + (p.isFromSheet ? ' • ' + (p.badge || 'HD') : '');
        return buildCardHtml(p, idx, 'cvOpenSerialCard', bTxt);
      }).join('');
      relSec.style.display = 'block';
    }

    // ২. Similar Titles (সাইটের + TMDB মিলিয়ে সেরাগুলো)
    var simSec = document.getElementById('cvSimilarSection');
    var simRow = document.getElementById('cvSimilarRow');
    if (!simSec || !simRow) return;

    var usedKeys = new Set(sortedParts.map(function(p) { return getLooseBaseKey(p.title); }));
    usedKeys.add(baseKey);

    var siteMatches = [];
    var curGenreWords = String(movie.genreText || movie.category || '').toLowerCase().split(/[,·\s]+/).filter(function(w) { return w.length >= 4; });
    var isCurAdult = (typeof isAdultMovie === 'function') ? isAdultMovie(movie) : false;

    if (Array.isArray(allMovies)) {
      allMovies.forEach(function(m) {
        if (m.id === movie.id || usedKeys.has(getLooseBaseKey(m.title))) return;
        if (!isCurAdult && typeof isAdultMovie === 'function' && isAdultMovie(m)) return;
        var mText = (m.category + ' ' + (m.genreText || '') + ' ' + (m.details || '')).toLowerCase();
        var score = 0;
        curGenreWords.forEach(function(w) { if (mText.indexOf(w) !== -1) score += 2; });
        if (m.isSeries === movie.isSeries) score += 1;
        if (score > 0) siteMatches.push({ m: m, score: score + (parseFloat(String(m.rating || '0').replace(/[^0-9.]/g, '')) || 0) * 0.2 });
      });
    }
    siteMatches.sort(function(a, b) { return b.score - a.score; });
    var picked = siteMatches.slice(0, 6).map(function(x) {
      usedKeys.add(getLooseBaseKey(x.m.title));
      return x.m;
    });

    if (tmdbId) {
      try {
        var recData = await resJsonSafe(await fetch('https://api.themoviedb.org/3/' + ep + '/' + tmdbId + '/recommendations?api_key=' + TMDB_API_KEY));
        var recItems = (recData && recData.results) || [];
        if (recItems.length < 4) {
          var simData = await resJsonSafe(await fetch('https://api.themoviedb.org/3/' + ep + '/' + tmdbId + '/similar?api_key=' + TMDB_API_KEY));
          recItems = recItems.concat((simData && simData.results) || []);
        }
        recItems.forEach(function(item) {
          if (picked.length >= 14 || !item.poster_path || (item.vote_average && item.vote_average < 5.5)) return;
          var tTitle = item.title || item.name || '';
          var k = getLooseBaseKey(tTitle);
          if (!k || usedKeys.has(k)) return;
          usedKeys.add(k);
          var localHit = findSheetMatchForPart(item.id, tTitle);
          picked.push(localHit || buildExternalMovieObj(Object.assign({}, item, { media_type: ep }), ''));
        });
      } catch (e) {}
    }

    if (!currentMovie || currentMovie.id !== openedId) return;
    similarCache = picked;
    if (picked.length > 0) {
      simRow.innerHTML = picked.map(function(m, idx) {
        return buildCardHtml(m, idx, 'cvOpenSimilarCard', null);
      }).join('');
      simSec.style.display = 'block';
    } else {
      simSec.style.display = 'none';
    }
  }

  window.loadRelatedParts = function() {};

  var prevOpenDetail = window.openCineDetailWithObj;
  if (typeof prevOpenDetail === 'function') {
    window.openCineDetailWithObj = function(movieObj) {
      prevOpenDetail(movieObj);
      loadSerialAndSimilar(movieObj);
    };
  }
})();

(function() {
  if (window._cvWatchUnlockPatched) return;
  window._cvWatchUnlockPatched = true;

  var watchUnlockMap = {};
  var pendingWatchId = null;
  var watchAdLeftAt = 0;
  var WATCH_AD_FALLBACK = 'https://directyp.org/4/c7e78de73c1a473eadfa5b2b5477313d';

  function getWatchAdUrl() {
    if (typeof ENTRY_AD_URL !== 'undefined' && ENTRY_AD_URL && /^https?:\/\//i.test(ENTRY_AD_URL)) {
      return ENTRY_AD_URL;
    }
    return WATCH_AD_FALLBACK;
  }

  function startMoviePlayerDirectly() {
    if (!currentMovie) return;
    stopHeroBgPreview();
    var pw = document.getElementById('cinePlayerWrap');
    var customUrl = (currentMovie.customWatchUrl || '').trim();
    var pSliders = document.getElementById('playerSlidersRow');
    var volBar = document.getElementById('playerVolumeBar');
    var watchBtn = document.querySelector('.btn-watch-online');
    if (watchBtn) watchBtn.innerHTML = '▶️ Watch Full Movie (আনলক সম্পন্ন ✅)';

    if (customUrl && (/^https?:\/\//i.test(customUrl) || /^www\./i.test(customUrl))) {
      document.getElementById('serverSelectionBar').style.display = 'none';
      loadCustomUrlIntoPlayer(customUrl);
      pw.style.display = 'block';
      pw.scrollIntoView({ behavior: 'smooth' });
      return;
    }

    resetPlayerElements();
    document.getElementById('serverSelectionBar').style.display = 'flex';
    if (pSliders) pSliders.style.display = 'flex';
    if (volBar) volBar.style.display = 'none';
    switchOnlineServer(1);
    pw.style.display = 'block';
    pw.scrollIntoView({ behavior: 'smooth' });
  }

  function completeWatchReturn() {
    if (!pendingWatchId || !currentMovie || currentMovie.id !== pendingWatchId) return;
    if (Date.now() - watchAdLeftAt < 1200) return;
    watchUnlockMap[currentMovie.id] = true;
    pendingWatchId = null;
    startMoviePlayerDirectly();
  }

  document.addEventListener('visibilitychange', function() {
    if (document.visibilityState === 'visible') completeWatchReturn();
  });
  window.addEventListener('focus', completeWatchReturn);

  var origOpenDetail = window.openCineDetailWithObj;
  if (typeof origOpenDetail === 'function') {
    window.openCineDetailWithObj = function(movieObj) {
      pendingWatchId = null;
      origOpenDetail(movieObj);
      var watchBtn = document.querySelector('.btn-watch-online');
      if (watchBtn && movieObj) {
        watchBtn.innerHTML = watchUnlockMap[movieObj.id]
          ? '▶️ Watch Full Movie (আনলক সম্পন্ন ✅)'
          : '▶️ Watch Full Movie (বিজ্ঞাপন দেখে দেখুন)';
      }
    };
  }

  window.playOnlineMovie = function() {
    if (!currentMovie) return;
    stopHeroBgPreview();
    var customUrl = (currentMovie.customWatchUrl || '').trim();
    if (!currentMovie.isFromSheet && !customUrl) {
      document.getElementById('nonSheetWatchModal').style.display = 'flex';
      return;
    }

    if ((typeof ADS_ENABLED !== 'undefined' && !ADS_ENABLED) || watchUnlockMap[currentMovie.id]) {
      startMoviePlayerDirectly();
      return;
    }

    pendingWatchId = currentMovie.id;
    watchAdLeftAt = Date.now();
    var watchBtn = document.querySelector('.btn-watch-online');
    if (watchBtn) watchBtn.innerHTML = '⏳ বিজ্ঞাপন ভালো করে দেখে ব্যাক আসেন...';
    openSafeUrl(getWatchAdUrl());
  };
})();

